from collections import OrderedDict

class LRUCache:
    """Least Recently Used cache with fixed capacity."""

    def __init__(self, capacity: int):
        """Initialize cache with maximum capacity."""
        if capacity <= 0:
            raise ValueError("Capacity must be positive")
        self.cache = OrderedDict()
        self.capacity = capacity
        self.hits = 0
        self.misses = 0

    def get(self, key):
        """Retrieve value by key, marking as recently used."""
        if key not in self.cache:
            self.misses += 1
            return -1
        self.hits += 1
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key, value) -> None:
        """Store a key-value pair, evicting LRU item if necessary."""
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

    def stats(self) -> dict:
        """Return cache statistics."""
        return {
            'hits': self.hits,
            'misses': self.misses,
            'size': len(self.cache)
        }

    def __len__(self) -> int:
        """Return the number of items currently in cache."""
        return len(self.cache)
